/root/autodl-tmp/RLinf/.venv/bin/python -c 'exec("""from tensorboard.backend.event_processing.event_accumulator import EventAccumulator as E\nimport glob, statistics\np=glob.glob(\"/root/autodl-tmp/experiments/rlt_teacher_dvac_w0to2_formal_fresh480_20260824_v1/tensorboard/events.out.tfevents.*\")[0]\ne=E(p); e.Reload()\ntags=[\n\"train/actor/rlt_dvac/weight_student_ref_error_corr\",\n\"train/actor/rlt_dvac/query_weight_q_gap_corr\",\n\"train/actor/rlt_dvac/replay_age_mean\",\n\"train/actor/rlt_dvac/replay_age_p95\",\n\"train/actor/rlt_dvac/query_mean_z_std\",\n\"train/actor/rlt_dvac/within_query_z_std\",\n\"train/actor/rlt_dvac/weight_mean\",\n\"train/actor/rlt_dvac/weight_ess_ratio\",\n\"train/actor/rlt_dvac/top20_weight_mass\",\n\"train/actor/rlt_dvac/min_weight_fraction\",\n\"train/actor/rlt_dvac/max_weight_fraction\",\n\"train/actor/rlt_dvac/downweighted_fraction\",\n\"train/actor/rlt_dvac/upweighted_fraction\",\n\"train/actor/weighted_q\",\n\"train/actor/weighted_bc\",\n\"train/actor/q_weight\",\n\"train/actor/bc_weight\",\n]\nprint(\"TAG COUNT FIRST_STEP LAST_STEP ACTIVE_MEAN ACTIVE_MEDIAN LAST\")\nfor t in tags:\n    vals=e.Scalars(t) if t in e.Tags()[\"scalars\"] else []\n    a=[v.value for v in vals if v.step>=136]\n    print(t,len(vals),vals[0].step if vals else None,vals[-1].step if vals else None,statistics.fmean(a) if a else None,statistics.median(a) if a else None,vals[-1].value if vals else None)\nfor prefix in [\"positive_reward\",\"nonpositive_reward\",\"student_route\",\"reference_route\"]:\n    sums={v.step:v.value for v in e.Scalars(f\"train/actor/rlt_dvac/{prefix}_weight_sum\")}\n    counts={v.step:v.value for v in e.Scalars(f\"train/actor/rlt_dvac/{prefix}_count\")}\n    ratios=[sums[k]/counts[k] for k in sorted(set(sums)&set(counts)) if k>=136 and counts[k]>0]\n    print(prefix+\"_weight_mean_derived\",len(ratios),statistics.fmean(ratios),statistics.median(ratios),ratios[-1])\nprint(\"HORIZON_ACTIVE_MEAN\")\nfor h in range(10):\n    vals=e.Scalars(f\"train/actor/rlt_dvac/weight_h{h:02d}\")\n    a=[v.value for v in vals if v.step>=136]\n    print(h,statistics.fmean(a),a[-1])\n""")'
